beforeExample:
package test;

import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;

public class Example {
    public void calculateLineHeight(StyledText textWidget, int offset) {
        int height = textWidget.getLineHeight(offset);
        System.out.println("Line height: " + height);
    }

    public static void main(String[] args) {
        Shell shell = new Shell();
        StyledText styledText = new StyledText(shell, SWT.NONE);
        Example example = new Example();
        example.calculateLineHeight(styledText, 0);
        shell.dispose();
    }
}

afterExample:
package test;

import org.eclipse.swt.custom.StyledText;
import org.eclipse.swt.widgets.Shell;
import org.eclipse.swt.SWT;
import org.eclipse.jface.text.JFaceTextUtil;

public class Example {
    public void calculateLineHeight(StyledText textWidget, int offset) {
        int height = JFaceTextUtil.computeLineHeight(textWidget, offset, offset + 1, 1);
        System.out.println("Line height: " + height);
    }

    public static void main(String[] args) {
        Shell shell = new Shell();
        StyledText styledText = new StyledText(shell, SWT.NONE);
        Example example = new Example();
        example.calculateLineHeight(styledText, 0);
        shell.dispose();
    }
}

